# ---------------------------------------------------------------- 4.4 threshold: subject knowledge, understanding and skills
L44 = dict(type='threshold', rung='threshold', force='threshold', forceFrom='4.1', level='fheq:6', appliesTo='honours graduates in Sociology',
           addressee='learner', award=HON)
def k44(i, about, fw, nb, when, q, **k):
    s('4.4.b%d' % i, **L44, about=about,
      aaw=("State this as a threshold standard: the least an honours graduate in Sociology should have shown, at FHEQ level 6 (FQHEIS level 10), here %s. "
           "Cite it as %s and do not call it a regulatory rule, a competence standard (4.3) or a master's expectation. "
           "Set it beside %s, spine:6 and %s; the statement gives no typical or excellent rung, so take classification language from Annex D, not from this item.")
          % (about, CITE % '4.4', fw, nb),
      aad=("Raise it when %s. Put it to a student in plain words as something they should be able to do by the end of the degree, and to staff as a floor every route through the course should let students reach. "
           "Ask: %s Do not read the list aloud or treat it as the mark of a good degree; it is the minimum.") % (when, q),
      **k)
